import{_ as a,o as d,c as t,aS as o}from"./chunks/framework.DsJaIkSj.js";const h=JSON.parse('{"title":"包职责目录","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/package-ownership.md","filePath":"catalog/package-ownership.md","lastUpdated":null}'),c={name:"catalog/package-ownership.md"};function r(n,e,s,i,l,m){return d(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="包职责目录" tabindex="-1">包职责目录 <a class="header-anchor" href="#包职责目录" aria-label="Permalink to &quot;包职责目录&quot;">​</a></h1><p>状态：当前权威（职责路由）；包版本、实际依赖和入口仍以各包 <code>package.json</code>、exports、源码与发布产物为准。</p><h2 id="职责层次" tabindex="-1">职责层次 <a class="header-anchor" href="#职责层次" aria-label="Permalink to &quot;职责层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>当前包</th><th>职责与关系</th></tr></thead><tbody><tr><td>基础视觉与运行时</td><td><code>@qynpm/ui</code>、<code>@qynpm/hooks</code>、<code>@qynpm/admin-theme</code>、<code>@qynpm/admin-framework</code></td><td>UI 提供公共组件；hooks 提供通用组合式能力；theme 提供 tokens 与当前 Element Plus 样式适配；admin-framework 提供后台运行时基础，并有 <code>./actions</code> 入口。</td></tr><tr><td>schema / adapter</td><td><code>@qynpm/form</code>、<code>@qynpm/table-schema</code>、<code>@qynpm/table</code></td><td>form 是 schema 表单工具；table-schema 描述表格 schema；table 组合表格能力。当前 metadata 显示这些包与 UI/Element Plus 有不同程度的 peer 关系，不能据此宣称 renderer 中立。</td></tr><tr><td>后台 patterns</td><td><code>@qynpm/admin-shell</code>、<code>@qynpm/admin-patterns</code></td><td>shell 提供受控视觉外壳；patterns 提供通用后台页面模式。二者目前均以 admin-framework/UI（shell 还以 admin-theme）为 peer 依赖。</td></tr><tr><td>业务公共模块</td><td><code>@qynpm/pickers</code>、<code>@qynpm/product-preview</code>、<code>@qynpm/qy-address-dialog</code>、<code>@qynpm/rich-text</code>、<code>@qynpm/excel-preview</code></td><td>为多个业务页面提供选择器、商品预览、地址弹窗、独立富文本编辑能力和表格数据预览；富文本包以 Qy HTML/上传协议为公开面，Quill 只作为内部 runtime adapter，Excel 包以 Qy 数据/列协议为公开面，x-data-spreadsheet 只作为内部 renderer。</td></tr><tr><td>业务消费者</td><td><code>qy-permission</code>、<code>qy-origin-app</code>；<code>qy-workspace</code> 为旧 ERP 证据</td><td>消费者决定自己的安装版本和解析结果。它们不定义本仓库的公共契约；workspace 仅用于旧行为、使用频率和迁移证据。</td></tr></tbody></table><p>层次用于解释依赖方向，不能替代当前源码证据或强制不存在的目录模板。兄弟包通过已发布的公开入口协作；具体运行时/入口规则见 <a href="./../contracts/package-exports-and-runtime">包 exports 与宿主 runtime</a>。</p><h2 id="已知边界风险" tabindex="-1">已知边界风险 <a class="header-anchor" href="#已知边界风险" aria-label="Permalink to &quot;已知边界风险&quot;">​</a></h2><ul><li><code>admin-framework</code>、<code>admin-shell</code> 与 <code>admin-patterns</code> 名称相近但职责相邻，修改依赖或公共 API 前须以各自 metadata 与消费者使用处核实，不能按名称推断可替代关系。</li><li><code>packages/QyAddressDialog</code> 与 <code>packages/qy-address-dialog</code> 均被 workspace 的 <code>packages/*</code> 收入，且都声明 <code>@qynpm/qy-address-dialog@1.0.1</code>；同名包与仅大小写不同的目录存在解析和跨平台风险。V1 仅登记该风险，后续须单独决策，不能在此直接删除或重命名目录。</li><li><code>table</code> 与 <code>table-schema</code> 是拆分的表格层；<code>form</code> 同属 schema 相关能力但有独立的运行时与 peer 依赖，不能合并叙述为同一发布包。</li><li><code>admin-theme</code> 导出 CSS/tokens/当前 Element Plus 样式适配；Qy tokens 才是长期视觉协议，<code>--el-*</code> 不应成为业务所需接口。</li><li>UI 的公开 interface 与当前 renderer 决策由 <a href="./../contracts/ui-public-interface">UI 公共 interface</a> 和 <a href="./../adr/2026-08-06-current-element-implementation-and-future-renderer-seam">renderer ADR</a> 统一说明。</li></ul>',7)])])}const u=a(c,[["render",r]]);export{h as __pageData,u as default};
